<?php
require_once 'config.php'; require_once 'includes/auth_check.php';
$id=(int)($_GET['id']??$_POST['complaint_id']??0); $message=''; $error='';
$stmt=$conn->prepare('SELECT id,reference_no,subject,status,feedback_rating,feedback_comment FROM complaints WHERE id=? AND user_id=? LIMIT 1'); $stmt->bind_param('ii',$id,$_SESSION['user_id']); $stmt->execute(); $complaint=$stmt->get_result()->fetch_assoc(); $stmt->close();
if(!$complaint){http_response_code(404);exit('Complaint not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){try{require_csrf(); if($complaint['status']!=='Resolved')throw new RuntimeException('Feedback is available after resolution.'); $rating=(int)($_POST['rating']??0); $comment=trim($_POST['feedback_comment']??''); if($rating<1||$rating>5)throw new RuntimeException('Choose a rating from 1 to 5 stars.'); $stmt=$conn->prepare('UPDATE complaints SET feedback_rating=?, feedback_comment=?, feedback_at=NOW() WHERE id=? AND user_id=?'); $stmt->bind_param('isii',$rating,$comment,$id,$_SESSION['user_id']); $stmt->execute();$stmt->close(); audit_log($conn,'feedback','complaint',$id,'Complaint feedback submitted with '.$rating.'/5 rating'); $message='Thank you. Your feedback has been saved.'; $complaint['feedback_rating']=$rating;$complaint['feedback_comment']=$comment;}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Complaint Feedback | Grievance Portal</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"></head><body class="bg-light"><div class="d-flex min-vh-100"><?php include 'includes/sidebar.php';?><main class="flex-grow-1"><header class="bg-white border-bottom p-3"><h4 class="mb-0">Complaint Feedback</h4><small class="text-muted">Help the institution improve its grievance service.</small></header><div class="container p-4"><div class="card border-0 shadow-sm" style="max-width:720px"><div class="card-body p-4"><div class="small text-muted"><?=e($complaint['reference_no'])?></div><h3><?=e($complaint['subject'])?></h3><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($complaint['status']!=='Resolved'):?><div class="alert alert-info">Feedback becomes available after this complaint is resolved.</div><?php elseif($complaint['feedback_rating']):?><div class="alert alert-success">You rated this resolution <strong><?=e($complaint['feedback_rating'])?>/5</strong>.</div><?php endif;?><form method="post"><?=csrf_field()?><input type="hidden" name="complaint_id" value="<?=$id?>"><label class="form-label">Service rating</label><div class="d-flex gap-2 mb-3" aria-label="Choose a rating"><?php for($i=1;$i<=5;$i++):?><label class="border rounded p-2 text-center"><input type="radio" name="rating" value="<?=$i?>" <?=$complaint['feedback_rating']==$i?'checked':''?> required><br><span class="fs-3 text-warning">★</span><br><small><?=$i?></small></label><?php endfor;?></div><label class="form-label">Comments</label><textarea class="form-control mb-3" name="feedback_comment" rows="4" maxlength="2000" placeholder="What went well, and what could be improved?"><?=e($complaint['feedback_comment']??'')?></textarea><button class="btn btn-primary" <?=$complaint['status']!=='Resolved'?'disabled':''?>>Save feedback</button></form></div></div></div></main></div></body></html>
